"""
Management Client (CLI) - a gRPC client of the Coordinator.

Usage:
    python3 client/cli.py register <participant_id>
    python3 client/cli.py create [--rounds N]
    python3 client/cli.py start <job_id>
    python3 client/cli.py status <job_id>

Options:
    --coordinator HOST:PORT   coordinator address (default: localhost:50051)
"""

import argparse
import os
import sys

import grpc

# Generated by scripts/generate_proto.sh into this folder
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import fl_pb2
import fl_pb2_grpc


def main():
    parser = argparse.ArgumentParser(description="Federated Learning management CLI")
    parser.add_argument("--coordinator", default="localhost:50051", help="coordinator address")
    sub = parser.add_subparsers(dest="command", required=True)

    p = sub.add_parser("register", help="register a participant")
    p.add_argument("participant_id")

    p = sub.add_parser("create", help="create a training experiment")
    p.add_argument("--rounds", type=int, default=1, help="number of training rounds")

    p = sub.add_parser("start", help="start a training job")
    p.add_argument("job_id")

    p = sub.add_parser("status", help="show job status and result")
    p.add_argument("job_id")

    args = parser.parse_args()
    stub = fl_pb2_grpc.CoordinatorStub(grpc.insecure_channel(args.coordinator))

    try:
        if args.command == "register":
            r = stub.RegisterParticipant(fl_pb2.RegisterParticipantRequest(participant_id=args.participant_id))
            print(("OK: " if r.success else "ERROR: ") + r.message)

        elif args.command == "create":
            r = stub.CreateExperiment(fl_pb2.CreateExperimentRequest(num_rounds=args.rounds))
            print(f"OK: {r.message}")
            print(f"Job ID: {r.job_id}")

        elif args.command == "start":
            r = stub.StartTraining(fl_pb2.StartTrainingRequest(job_id=args.job_id))
            print(("OK: " if r.success else "ERROR: ") + r.message)

        elif args.command == "status":
            s = stub.GetTrainingStatus(fl_pb2.GetTrainingStatusRequest(job_id=args.job_id))
            print(f"Job:           {s.job_id}")
            print(f"Status:        {fl_pb2.JobStatus.Name(s.status)}")
            print(f"Round:         {s.current_round}/{s.num_rounds}")
            print(f"Results:       {s.results_received}/{s.total_participants} received this round")
            print(f"Global weight: {s.global_weight}")

    except grpc.RpcError as e:
        if e.code() == grpc.StatusCode.UNAVAILABLE:
            print(f"ERROR: cannot reach the coordinator at {args.coordinator}. Is it running?")
        else:
            print(f"ERROR: {e.details()}")
        sys.exit(1)


if __name__ == "__main__":
    main()
